  RectTransform Node(Transform parent,string name){var go=new GameObject(name,typeof(RectTransform));go.transform.SetParent(parent,false);return go.GetComponent<RectTransform>();}
  void Anchor(RectTransform r,Vector2 anchor,Vector2 pivot,Vector2 size,Vector2 position){r.anchorMin=r.anchorMax=anchor;r.pivot=pivot;r.sizeDelta=size;r.anchoredPosition=position;}
  void Position(RectTransform r,Rect rect){Anchor(r,new Vector2(0,1),new Vector2(0,1),rect.size,new Vector2(rect.x,-rect.y));}
  RectTransform Surface(Transform parent,string name,Vector2 size,Vector2 position,Vector2 anchor,Vector2 pivot){var r=Node(parent,name);Anchor(r,anchor,pivot,size,position);r.gameObject.AddComponent<Image>().color=bg;return r;}
  TextMeshProUGUI Text(Transform parent,string value,int size,Color color,Rect rect){var r=Node(parent,"文字");Position(r,rect);var t=r.gameObject.AddComponent<TextMeshProUGUI>();t.font=font;t.fontSize=size;t.enableAutoSizing=true;t.fontSizeMin=Mathf.Min(size,18);t.fontSizeMax=size;t.text=value;t.color=color;t.enableWordWrapping=true;t.overflowMode=TextOverflowModes.Ellipsis;t.raycastTarget=false;return t;}
  Button Button(Transform parent,string title,Action action,Rect rect,bool enabled=true){var r=Node(parent,title);Position(r,rect);r.gameObject.AddComponent<Image>().color=button;var b=r.gameObject.AddComponent<Button>();var c=b.colors;c.normalColor=Color.white;c.highlightedColor=new Color(.75f,.91f,.88f);c.pressedColor=new Color(.60f,.76f,.72f);c.disabledColor=new Color(.55f,.62f,.62f,.7f);b.colors=c;b.targetGraphic=r.GetComponent<Image>();b.interactable=enabled;b.onClick.AddListener(()=>{game.Cue();action();});var t=Text(r,title,20,enabled?ink:dim,new Rect(8,5,rect.width-16,rect.height-8));t.alignment=TextAlignmentOptions.Center;return b;}
