  public void RebuildPanel(){if(panel!=null){panel.gameObject.SetActive(false);Destroy(panel.gameObject);}if(game.Panel==0&&!game.Paused)return;
   panel=Surface(root,"当前窗口",new Vector2(470,780),new Vector2(-24,0),new Vector2(1,.5f),new Vector2(1,.5f));if(game.Panel!=3)Button(panel,"关闭  ×",()=>{game.Panel=0;game.BuildMode=false;if(game.Paused){game.Paused=false;Time.timeScale=1;}RebuildPanel();},new Rect(330,16,120,44));
