   if(game.Panel==1){Text(panel,"当前选择："+(char)('A'+game.SelectedTank)+"位",24,ink,new Rect(24,185,420,45));Text(panel,"固定落位保留行走通道。\n首缸免费，新缸35金币。",21,dim,new Rect(24,236,420,82));Button(panel,game.save.tanks[game.SelectedTank].built?"此处已有展缸":"确认摆放实体鱼缸 · "+game.BuildCost+"金币",()=>game.BuildTank(),new Rect(24,330,420,62),!game.save.tanks[game.SelectedTank].built&&game.save.coins>=game.BuildCost);Button(panel,"切换沙地 / 海带布景",()=>game.ChangeTankTheme(),new Rect(24,410,420,54),game.save.tanks[game.SelectedTank].built);Button(panel,"管理缸内的鱼",()=>game.OpenPanel(2),new Rect(24,480,420,54),game.save.tanks[game.SelectedTank].built);Button(panel,game.save.shellDisplay?"收起贝壳摆件":"摆放带回的贝壳",()=>game.ToggleShellDisplay(),new Rect(24,550,420,54),game.save.shells.Any(x=>x));Button(panel,game.save.anchorDisplay?"收起旧船锚":"展示打捞的旧船锚",()=>game.ToggleAnchorDisplay(),new Rect(24,620,420,54),game.save.salvaged);Button(panel,"返回码头",()=>game.LeaveRoom(),new Rect(24,700,420,52));return;}
