  RectTransform Scroll(Transform parent,Rect rect){var outer=Node(parent,"物品列表");Position(outer,rect);outer.gameObject.AddComponent<Image>().color=bg;outer.gameObject.AddComponent<RectMask2D>();var scroll=outer.gameObject.AddComponent<ScrollRect>();var content=Node(outer,"列表内容");content.anchorMin=new Vector2(0,1);content.anchorMax=Vector2.one;content.pivot=new Vector2(.5f,1);content.offsetMin=content.offsetMax=Vector2.zero;var layout=content.gameObject.AddComponent<VerticalLayoutGroup>();layout.spacing=10;layout.childControlHeight=true;layout.childControlWidth=true;layout.childForceExpandHeight=false;layout.childForceExpandWidth=true;var fit=content.gameObject.AddComponent<ContentSizeFitter>();fit.verticalFit=ContentSizeFitter.FitMode.PreferredSize;scroll.content=content;scroll.viewport=outer;scroll.horizontal=false;scroll.movementType=ScrollRect.MovementType.Clamped;return content;}
